diff --git a/fftools/ffmpeg.h b/fftools/ffmpeg.h
index 429c1aba85..d4848f7813 100644
--- a/fftools/ffmpeg.h
+++ b/fftools/ffmpeg.h
@@ -274,21 +274,22 @@ typedef struct FilterGraph {
     const AVClass *class;
     int            index;

     InputFilter   **inputs;
     int          nb_inputs;
     OutputFilter **outputs;
     int         nb_outputs;
 } FilterGraph;

 typedef struct Decoder {
-    char dummy;
+    uint8_t         *subtitle_header;
+    int              subtitle_header_size;
 } Decoder;

 typedef struct InputStream {
     const AVClass *class;

     /* parent source */
     struct InputFile *file;

     int index;

diff --git a/fftools/ffmpeg_dec.c b/fftools/ffmpeg_dec.c
index 16f653d52f..5e23b143d6 100644
--- a/fftools/ffmpeg_dec.c
+++ b/fftools/ffmpeg_dec.c
@@ -79,20 +79,22 @@ void dec_free(Decoder **pdec)
         return;
     dp = dp_from_dec(dec);

     av_frame_free(&dp->frame);
     av_packet_free(&dp->pkt);

     for (int i = 0; i < FF_ARRAY_ELEMS(dp->sub_prev); i++)
         av_frame_free(&dp->sub_prev[i]);
     av_frame_free(&dp->sub_heartbeat);

+    av_freep(&dp->dec.subtitle_header);
+
     av_freep(pdec);
 }

 static int dec_alloc(Decoder **pdec)
 {
     DecoderPriv *dp;

     *pdec = NULL;

     dp = av_mallocz(sizeof(*dp));
@@ -962,12 +964,22 @@ int dec_open(InputStream *ist, Scheduler *sch, unsigned sch_idx)
     if ((ret = avcodec_open2(ist->dec_ctx, codec, &ist->decoder_opts)) < 0) {
         av_log(ist, AV_LOG_ERROR, "Error while opening decoder: %s\n",
                av_err2str(ret));
         return ret;
     }

     ret = check_avoptions(ist->decoder_opts);
     if (ret < 0)
         return ret;

+    if (ist->dec_ctx->subtitle_header) {
+        /* ASS code assumes this buffer is null terminated so add extra byte. */
+        dp->dec.subtitle_header = av_mallocz(ist->dec_ctx->subtitle_header_size + 1);
+        if (!dp->dec.subtitle_header)
+            return AVERROR(ENOMEM);
+        memcpy(dp->dec.subtitle_header, ist->dec_ctx->subtitle_header,
+               ist->dec_ctx->subtitle_header_size);
+        dp->dec.subtitle_header_size = ist->dec_ctx->subtitle_header_size;
+    }
+
     return 0;
 }

diff --git a/fftools/ffmpeg_enc.c b/fftools/ffmpeg_enc.c
index 2a7fba0c51..bbd86a6fe1 100644
--- a/fftools/ffmpeg_enc.c
+++ b/fftools/ffmpeg_enc.c
@@ -164,21 +164,21 @@ static int set_encoder_id(OutputFile *of, OutputStream *ost)

     return 0;
 }

 int enc_open(void *opaque, const AVFrame *frame)
 {
     OutputStream *ost = opaque;
     InputStream *ist = ost->ist;
     Encoder              *e = ost->enc;
     AVCodecContext *enc_ctx = ost->enc_ctx;
-    AVCodecContext *dec_ctx = NULL;
+    Decoder            *dec;
     const AVCodec      *enc = enc_ctx->codec;
     OutputFile          *of = ost->file;
     FrameData *fd;
     int frame_samples = 0;
     int ret;

     if (e->opened)
         return 0;

     // frame is always non-NULL for audio and video
@@ -186,23 +186,22 @@ int enc_open(void *opaque, const AVFrame *frame)

     if (frame) {
         av_assert0(frame->opaque_ref);
         fd = (FrameData*)frame->opaque_ref->data;
     }

     ret = set_encoder_id(of, ost);
     if (ret < 0)
         return ret;

-    if (ist) {
-        dec_ctx = ist->dec_ctx;
-    }
+    if (ist)
+        dec = ist->decoder;

     // the timebase is chosen by filtering code
     if (ost->type == AVMEDIA_TYPE_AUDIO || ost->type == AVMEDIA_TYPE_VIDEO) {
         enc_ctx->time_base      = frame->time_base;
         enc_ctx->framerate      = fd->frame_rate_filter;
         ost->st->avg_frame_rate = fd->frame_rate_filter;
     }

     switch (enc_ctx->codec_type) {
     case AVMEDIA_TYPE_AUDIO:
@@ -272,28 +271,30 @@ int enc_open(void *opaque, const AVFrame *frame)
     case AVMEDIA_TYPE_SUBTITLE:
         if (ost->enc_timebase.num)
             av_log(ost, AV_LOG_WARNING,
                    "-enc_time_base not supported for subtitles, ignoring\n");
         enc_ctx->time_base = AV_TIME_BASE_Q;

         if (!enc_ctx->width) {
             enc_ctx->width     = ost->ist->par->width;
             enc_ctx->height    = ost->ist->par->height;
         }
-        if (dec_ctx && dec_ctx->subtitle_header) {
+
+        av_assert0(dec);
+        if (dec->subtitle_header) {
             /* ASS code assumes this buffer is null terminated so add extra byte. */
-            enc_ctx->subtitle_header = av_mallocz(dec_ctx->subtitle_header_size + 1);
+            enc_ctx->subtitle_header = av_mallocz(dec->subtitle_header_size + 1);
             if (!enc_ctx->subtitle_header)
                 return AVERROR(ENOMEM);
-            memcpy(enc_ctx->subtitle_header, dec_ctx->subtitle_header,
-                   dec_ctx->subtitle_header_size);
-            enc_ctx->subtitle_header_size = dec_ctx->subtitle_header_size;
+            memcpy(enc_ctx->subtitle_header, dec->subtitle_header,
+                   dec->subtitle_header_size);
+            enc_ctx->subtitle_header_size = dec->subtitle_header_size;
         }

         break;
     default:
         av_assert0(0);
         break;
     }

     if (ost->bitexact)
         enc_ctx->flags |= AV_CODEC_FLAG_BITEXACT;

